INT WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, INT nShowCmd) {
    // Crear la ventana principal
    WNDCLASS wc = { 0 };
    wc.lpfnWndProc = DefWindowProc;
    wc.hInstance = hInstance;
    wc.lpszClassName = L"MySnakeWindow";
    RegisterClass(&wc);
    hWnd = CreateWindowEx(WS_EX_CLIENTEDGE, wc.lpszClassName, L"My Snake Game", WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, WINDOW_WIDTH, WINDOW_HEIGHT, NULL, NULL, hInstance, NULL);

    // Cargar las imágenes
    HBITMAP snake_img = LoadBitmap(hInstance, L"snake");
    HBITMAP food_img = LoadBitmap(hInstance, L"food");

    // Inicializar las variables
    snake.x = WINDOW_WIDTH / 2;
    snake.y = WINDOW_HEIGHT / 2;
    snake.dir = 0;
    food.x = rand() % (WINDOW_WIDTH / SNAKE_SIZE) * SNAKE_SIZE;
    food.y = rand() % (WINDOW_HEIGHT / SNAKE_SIZE) * SNAKE_SIZE;

    // Bucle principal del juego
    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);

        if (!game_over) {
            // Actualizar el juego
            UpdateGame();
            // Dibujar la pantalla
            DrawGame(snake_img, food_img);
        }
    }

    // Liberar las imágenes
    DeleteObject(snake_img);
    DeleteObject(food_img);

    return msg.wParam;
}
