void DrawGame(HBITMAP snake_img, HBITMAP food_img) {
    // Limpiar la pantalla
    HDC hdc = GetDC(hWnd);
    HBRUSH brush = CreateSolidBrush(RGB(255, 255, 255));
    FillRect(hdc, (RECT*) &RECT{ 0, 0, WINDOW_WIDTH, WINDOW_HEIGHT }, brush);
    ReleaseDC(hWnd, hdc);
    DeleteObject(brush);

    // Dibujar la serpiente
    HDC memdc = CreateCompatibleDC(hdc);
    HBITMAP bitmap = CreateCompatibleBitmap(hdc, WINDOW_WIDTH, WINDOW_HEIGHT);
    SelectObject(memdc, bitmap);
    BitBlt(memdc, 0, 0, WINDOW_WIDTH, WINDOW_HEIGHT, hdc, 0, 0, SRCCOPY);

    for (int I = 0; I < snake.length; i++) {
        BitBlt(memdc, snake.body[i].x, snake.body[i].y, SNAKE_SIZE, SNAKE_SIZE, hInstance, snake_img, SRCCOPY);
    }

    BitBlt(hdc, 0, 0, WINDOW_WIDTH, WINDOW_HEIGHT, memdc, 0, 0, SRCPAINT);
    DeleteDC(memdc);
    DeleteObject(bitmap);

    // Dibujar la comida
    HDC memdc2 = CreateCompatibleDC(hdc);
    HBITMAP bitmap2 = CreateCompatibleBitmap(hdc, WINDOW_WIDTH, WINDOW_HEIGHT);
    SelectObject(memdc2, bitmap2);
    BitBlt(memdc2, 0, 0, WINDOW_WIDTH, WINDOW_HEIGHT, hdc, 0, 0, SRCCOPY);

    BitBlt(memdc2, food.x, food.y, SNAKE_SIZE, SNAKE_SIZE, hInstance, food_img, SRCCOPY);

    BitBlt(hdc, 0, 0, WINDOW_WIDTH, WINDOW_HEIGHT, memdc2, 0, 0, SRCPAINT);
    DeleteDC(memdc2);
    DeleteObject(bitmap2);
}
