    <div id="modal" class="modal">
      <span class="close">&times;</span>
      <div class="modal-content">
        <div class="chat-container">
          <div class="chat-message">
            <div class="chat-message__text is-bot">Hola! ¿Cómo puedo ayudarte?</div>
          </div>
          <div class="chat-message">
            <div class="chat-message__text">Hola, estoy interesado en sus servicios.</div>
          </div>
          <div class="chat-message">
            <div class="chat-message__text is-bot">Genial, ¿podrías proporcionar más detalles sobre tus necesidades?</div>
          </div>
          <div class="chat-message">
            <div class="chat-message__text">Claro, necesito ayuda con mi sitio web, ¿podría proporcionarme algunos consejos?</div>
          </div>
        </div>
      </div>
    </div>

    <script>
      // Función para abrir el modal
